=== 3. THE MERGE SCRIPT (I RAN THIS - it produced 828 points / 756 enriched / 3024 cloze-ready) ===
import json, glob, re, unicodedata

def norm(t):
    t = unicodedata.normalize('NFKC', t)
    t = re.sub(r'\s*[（(][^（()]*[)）]\s*$', '', t)   # strip trailing romaji parenthetical
    t = re.sub(r'[\s　]', '', t).replace('〜', '～')  # unify wave dash
    return t

gk = {}
for f in glob.glob('gokan-dataset/compiled/grammar/points/*.json'):
    p = json.load(open(f, encoding='utf-8'))
    gk[(p['jlptLevel'], norm(p['title']))] = p

for L, n in [('N5',5), ('N4',4), ('N3',3), ('N2',2), ('N1',1)]:
    rows = []
    hb = json.load(open(f'hanabira/grammar_ja_{L}_full_alphabetical_0001.json', encoding='utf-8'))
    for i, h in enumerate(hb):
        g = gk.get((n, norm(h['title'])))
        rows.append({
            'id':        g['id'] if g else f'{L.lower()}-hb{i:03d}',
            'level':     L,
            'title':     norm(h['title']),
            'romaji':    (g or {}).get('romaji'),
            'short':     h['short_explanation'],
            'long':      h['long_explanation'],
            'formation': h['formation'],
            'kind':      (g or {}).get('kind', 'construction'),   # construction | inflection
            'family':    (g or {}).get('family'),                 # {id,name,relatedPoints[],axis}
            'usageNote': (g or {}).get('usageNote'),
            'formality': (g or {}).get('formalityLevel'),
            # gokan examples carry words[] + patternWordIndices; hanabira ones are plain jp/romaji/en
            'examples':  g['examples'] if g else h['examples'],
            'enriched':  bool(g),
        })
    json.dump(rows, open(f'app/data/grammar/{L.lower()}.json','w',encoding='utf-8'),
              ensure_ascii=False, separators=(',',':'))
# then gzip each output; measured 72/70/86/140/174 KB gz for N5..N1

=== 4. EXERCISE GENERATORS (all four run off fields that already exist) ===
function makeExercises(point, CONJUGATIONS) {
  const out = [];
  for (const ex of point.examples) {
    if (!ex.words) continue;                        // plain hanabira example: display only

    // (a) CLOZE - only for constructions; blank the grammar marker itself
    if (point.kind === 'construction' && ex.patternWordIndices.length) {
      out.push({ type:'cloze', jp: ex.jp, en: ex.en,
        blanks: ex.patternWordIndices,
        answer: ex.patternWordIndices.map(i => ex.words[i].surface).join(''),
        // hard distractors = this point's near-synonyms, NOT random strings
        distractors: (point.family?.relatedPoints ?? []).slice(0, 3) });
    }

    // (b) PICK-THE-PARTICLE - unresolved single-kana tokens are particles
    const P = new Set(['は','が','を','に','で','と','へ','も','の','から','まで','や','ね','よ','か']);
    ex.words.forEach((w, i) => { if (!w.vocabId && P.has(w.surface))
      out.push({ type:'particle', jp: ex.jp, en: ex.en, blank: i, answer: w.surface,
                 distractors: [...P].filter(p => p !== w.surface).sort(() => Math.random()-0.5).slice(0,3) }); });

    // (c) SENTENCE ORDERING - words[] concatenates back to jp exactly, so validation is free
    if (ex.words.length >= 4 && ex.words.length <= 12)
      out.push({ type:'order', tiles: shuffle(ex.words.map(w => w.surface)), answer: ex.jp, en: ex.en });
  }

  // (d) TRANSFORM - inflection points only (14 of them); table is pre-built
  const conj = CONJUGATIONS[point.id];   // compiled/grammar/conjugations.json
  if (conj) for (const it of conj.items)
    out.push({ type:'transform', prompt: it.lemma, promptReading: it.lemmaReading,
               instruction: conj.formLabel, answer: it.target,
               answerReading: it.targetReading, hint: it.wordClass });
  return out;
}

